(window.__qhadithX=window.__qhadithX||{})[43]={"13":[{"c":"Shama'il Muhammadiyah","r":"Hadith 232","u":"https://quranx.com/Hadith/Shamail/Reference/Hadith-232","x":"'Ali ibn Rabi'a said:\n\n\"I was present when 'Ali (may Allah be well pleased with him) had an animal brought for him to ride. When he placed his foot in the stirrup, he said: \"In the Name of Allah [Bismillah],\" and when he settled on its back, he said: \"Praise be to Allah!\" Then he said: \"Glory be to the One who has placed this at our disposal, for we would not have been equal to the task [Subhanalladhi sakhkhara la-na hadha wa ma kunna la-hu muqrinin], and to our Lord we are surely returning [wa inna ila Rabbina la-munqalibun]. (Al-Qur'an;43:13-14)Then he said: \"Praise be to Allah,\" three times, and: \"Allah is Supremely Great,\" three times, then: \"Glory be to You! I have wronged myself, so forgive me, for no one forgives sins but You!\" Then he laughed, so I said to him: \"What has made you laugh, O Commander of the Believers?\" He said: \"I saw Allah’s Messenger (Allah bless him and give him peace) do just as I did now, after which he laughed, so I said: \"What has made you laugh, O Messenger of Allah?\" He replied: ‘Your Lord surely marvels at His servant when he says: \"My Lord, forgive me my sins, knowing that no one but He forgives sins'!\"","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، قَالَ‏:‏ حَدَّثَنَا أَبُو الأَحْوَصِ، عَنْ أَبِي إِسْحَاقَ، عَنْ عَلِيِّ بْنِ رَبِيعَةَ، قَالَ‏:‏ شَهِدْتُ عَلِيًّا، أُتِيَ بِدَابَّةٍ لِيَرْكَبَهَا فَلَمَّا وَضَعَ رِجْلَهُ فِي الرِّكَابِ، قَالَ‏:‏ بِسْمِ اللهِ، فَلَمَّا اسْتَوَى عَلَى ظَهْرِهَا، قَالَ‏:‏ الْحَمْدُ لِلَّهِ، ثُمَّ قَالَ‏:‏ سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ، ثُمَّ قَالَ‏:‏ الْحَمْدُ لِلَّهِ ثَلاثًا، وَاللَّهُ أَكْبَرُ ثَلاثًا، سُبْحَانَكَ إِنِّي ظَلَمْتُ نَفْسِي، فَاغْفِرْ لِي فَإِنَّهُ لا يَغْفِرُ الذُّنُوبَ إِلا أَنْتَ، ثُمَّ ضَحِكَ فَقُلْتُ‏:‏ مِنْ أَيِّ شَيْءٍ ضَحِكْتَ يَا أَمِيرَ الْمُؤْمِنِينَ‏؟‏ قَالَ‏:‏ رَأَيْتُ رَسُولَ اللهِ صلى الله عليه وسلم صَنَعَ كَمَا صَنَعْتُ ثُمَّ ضَحِكَ، فَقُلْتُ‏:‏ مِنْ أَيِّ شَيْءٍ ضَحِكْتَ يَا رَسُولَ اللهِ‏؟‏ قَالَ‏:‏ إِنَّ رَبَّكَ لَيَعْجَبُ مِنْ عَبْدِهِ، إِذَا قَالَ‏:‏ رَبِّ اغْفِرْ لِي ذُنُوبِي، إِنَّهُ لا يَغْفِرُ الذُّنُوبَ غَيْرُكَ‏.‏‏","v":[]}],"14":[{"c":"Shama'il Muhammadiyah","r":"Hadith 232","u":"https://quranx.com/Hadith/Shamail/Reference/Hadith-232","x":"'Ali ibn Rabi'a said:\n\n\"I was present when 'Ali (may Allah be well pleased with him) had an animal brought for him to ride. When he placed his foot in the stirrup, he said: \"In the Name of Allah [Bismillah],\" and when he settled on its back, he said: \"Praise be to Allah!\" Then he said: \"Glory be to the One who has placed this at our disposal, for we would not have been equal to the task [Subhanalladhi sakhkhara la-na hadha wa ma kunna la-hu muqrinin], and to our Lord we are surely returning [wa inna ila Rabbina la-munqalibun]. (Al-Qur'an;43:13-14)Then he said: \"Praise be to Allah,\" three times, and: \"Allah is Supremely Great,\" three times, then: \"Glory be to You! I have wronged myself, so forgive me, for no one forgives sins but You!\" Then he laughed, so I said to him: \"What has made you laugh, O Commander of the Believers?\" He said: \"I saw Allah’s Messenger (Allah bless him and give him peace) do just as I did now, after which he laughed, so I said: \"What has made you laugh, O Messenger of Allah?\" He replied: ‘Your Lord surely marvels at His servant when he says: \"My Lord, forgive me my sins, knowing that no one but He forgives sins'!\"","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، قَالَ‏:‏ حَدَّثَنَا أَبُو الأَحْوَصِ، عَنْ أَبِي إِسْحَاقَ، عَنْ عَلِيِّ بْنِ رَبِيعَةَ، قَالَ‏:‏ شَهِدْتُ عَلِيًّا، أُتِيَ بِدَابَّةٍ لِيَرْكَبَهَا فَلَمَّا وَضَعَ رِجْلَهُ فِي الرِّكَابِ، قَالَ‏:‏ بِسْمِ اللهِ، فَلَمَّا اسْتَوَى عَلَى ظَهْرِهَا، قَالَ‏:‏ الْحَمْدُ لِلَّهِ، ثُمَّ قَالَ‏:‏ سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ، ثُمَّ قَالَ‏:‏ الْحَمْدُ لِلَّهِ ثَلاثًا، وَاللَّهُ أَكْبَرُ ثَلاثًا، سُبْحَانَكَ إِنِّي ظَلَمْتُ نَفْسِي، فَاغْفِرْ لِي فَإِنَّهُ لا يَغْفِرُ الذُّنُوبَ إِلا أَنْتَ، ثُمَّ ضَحِكَ فَقُلْتُ‏:‏ مِنْ أَيِّ شَيْءٍ ضَحِكْتَ يَا أَمِيرَ الْمُؤْمِنِينَ‏؟‏ قَالَ‏:‏ رَأَيْتُ رَسُولَ اللهِ صلى الله عليه وسلم صَنَعَ كَمَا صَنَعْتُ ثُمَّ ضَحِكَ، فَقُلْتُ‏:‏ مِنْ أَيِّ شَيْءٍ ضَحِكْتَ يَا رَسُولَ اللهِ‏؟‏ قَالَ‏:‏ إِنَّ رَبَّكَ لَيَعْجَبُ مِنْ عَبْدِهِ، إِذَا قَالَ‏:‏ رَبِّ اغْفِرْ لِي ذُنُوبِي، إِنَّهُ لا يَغْفِرُ الذُّنُوبَ غَيْرُكَ‏.‏‏","v":[]}],"58":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3253","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3253","x":"Narrated Abu Umamah:\n\nthat the Messenger of Allah (ﷺ) said: \"No people go astray after having been guided, but they resort to arguing.\" Then the Messenger of Allah (ﷺ) recited this Ayah: '...They quoted not the above example except for argument. Nay! But they are quarrelsome people... (43:58)'","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا مُحَمَّدُ بْنُ بِشْرٍ، وَيَعْلَى بْنُ عُبَيْدٍ، عَنْ حَجَّاجِ بْنِ دِينَارٍ، عَنْ أَبِي غَالِبٍ، عَنْ أَبِي أُمَامَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ مَا ضَلَّ قَوْمٌ بَعْدَ هُدًى كَانُوا عَلَيْهِ إِلاَّ أُوتُوا الْجَدَلَ ‏\"‏ ‏.‏ ثُمَّ تَلاَ رَسُولُ اللَّهِ صلى الله عليه وسلم هَذِهِ الآيَةَ ‏:‏ ‏(‏ما ضَرَبُوهُ لَكَ إِلاَّ جَدَلاً بَلْ هُمْ قَوْمٌ خَصِمُونَ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ إِنَّمَا نَعْرِفُهُ مِنْ حَدِيثِ حَجَّاجِ بْنِ دِينَارٍ ‏.‏ وَحَجَّاجٌ ثِقَةٌ مُقَارِبُ الْحَدِيثِ وَأَبُو غَالِبٍ اسْمُهُ حَزَوَّرُ ‏.‏","v":[]}],"72":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3246","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3246","x":"Narrated Abu Hurairah:\n\nthat the Prophet (ﷺ) said: \"A caller will call out: 'You shall have life and never die; you shall be healthy and never be ill; you shall be young and never grow old; you shall live in favor and never suffer difficult circumstances.' That is the saying of Allah Most High: This is Paradise, which you have been made to inherit because of your deeds that you used to do (43:72).\"","ar":"حَدَّثَنَا مَحْمُودُ بْنُ غَيْلاَنَ، وَغَيْرُ، وَاحِدٍ، قَالُوا حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا الثَّوْرِيُّ، أَخْبَرَنِي أَبُو إِسْحَاقَ، أَنَّ الأَغَرَّ أَبَا مُسْلِمٍ، حَدَّثَهُ عَنْ أَبِي سَعِيدٍ، وَأَبِي، هُرَيْرَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ يُنَادِي مُنَادٍ إِنَّ لَكُمْ أَنْ تَحْيَوْا فَلاَ تَمُوتُوا أَبَدًا وَإِنَّ لَكُمْ أَنْ تَصِحُّوا فَلاَ تَسْقَمُوا أَبَدًا وَإِنَّ لَكُمْ أَنْ تَشِبُّوا فَلاَ تَهْرَمُوا أَبَدًا وَإِنَّ لَكُمْ أَنْ تَنْعَمُوا فَلاَ تَبْأَسُوا أَبَدًا ‏\"‏ ‏.‏ فَذَلِكَ قَوْلُهُ تَعَالَى ‏:‏ ‏(‏وَ تِلْكَ الْجَنَّةُ الَّتِي أُورِثْتُمُوهَا بِمَا كُنْتُمْ تَعْمَلُونَ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى وَرَوَى ابْنُ الْمُبَارَكِ وَغَيْرُهُ هَذَا الْحَدِيثَ عَنِ الثَّوْرِيِّ وَلَمْ يَرْفَعُوهُ ‏.‏","v":[]}],"77":[{"c":"Sahih Bukhari","r":"Hadith 3230","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3230","x":"Narrated Yali:\n\nI heard the Prophet (ﷺ) reciting the following Verse on the pulpit: \"They will call: O Malik...' and Sufyan said that `Abdullah recited it: 'They will call: O Mali...' (43.77)","ar":"حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا سُفْيَانُ، عَنْ عَمْرٍو، عَنْ عَطَاءٍ، عَنْ صَفْوَانَ بْنِ يَعْلَى، عَنْ أَبِيهِ ـ رضى الله عنه ـ قَالَ سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقْرَأُ عَلَى الْمِنْبَرِ ‏{‏وَنَادَوْا يَا مَالِكُ‏}‏‏.‏ قَالَ سُفْيَانُ فِي قِرَاءَةِ عَبْدِ اللَّهِ وَنَادَوْا يَا مَالِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3266","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3266","x":"Narrated Yali:\n\nThat he heard the Prophet (ﷺ) on the pulpit reciting:-- \"They will cry: \"O Malik!' (43.77) (Malik is the gate-keeper (angel) of the (Hell) Fire.)","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا سُفْيَانُ، عَنْ عَمْرٍو، سَمِعَ عَطَاءً، يُخْبِرُ عَنْ صَفْوَانَ بْنِ يَعْلَى، عَنْ أَبِيهِ، أَنَّهُ سَمِعَ النَّبِيَّ صلى الله عليه وسلم يَقْرَأُ عَلَى الْمِنْبَرِ ‏{‏وَنَادَوْا يَا مَالِكُ ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4819","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4819","x":"Narrated Ya`la:\n\nI heard the Prophet (ﷺ) reciting when on the pulpit: 'They will cry, \"O Malik (Keeper of Hell) Let your Lord make an end of us.' (43.77)","ar":"حَدَّثَنَا حَجَّاجُ بْنُ مِنْهَالٍ، حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنْ عَمْرٍو، عَنْ عَطَاءٍ، عَنْ صَفْوَانَ بْنِ يَعْلَى، عَنْ أَبِيهِ، قَالَ سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقْرَأُ عَلَى الْمِنْبَرِ ‏{‏وَنَادَوْا يَا مَالِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ‏}‏ وَقَالَ قَتَادَةُ مَثَلاً لِلآخِرِينَ عِظَةً ‏لِمَنْ بَعْدَهُمْ.‏ وَقَالَ غَيْرُهُ ‏{‏مُقْرِنِينَ‏}‏ ضَابِطِينَ يُقَالُ فُلاَنٌ مُقْرِنٌ لِفُلاَنٍ ضَابِطٌ لَهُ وَالأَكْوَابُ الأَبَارِيقُ الَّتِي لاَ خَرَاطِيمَ لَهَا ‏{‏أَوَّلُ الْعَابِدِينَ‏}‏ أَىْ مَا كَانَ فَأَنَا أَوَّلُ الأَنِفِينَ وَهُمَا لُغَتَانِ رَجُلٌ عَابِدٌ وَعَبِدٌ وَقَرَأَ عَبْدُ اللَّهِ ‏{‏وَقَالَ الرَّسُولُ يَا رَبِّ‏}‏ وَيُقَالُ أَوَّلُ الْعَابِدِينَ الْجَاحِدِينَ مِنْ عَبِدَ يَعْبَدُ‏.‏","v":[]}]};